#   각 클래스에 @SpringBootTest 와 @MockBean 을 직접

@SpringBootTest
class OrderServiceTest {
    @MockBean MailSendClient mailSendClient;
}

@SpringBootTest
class ProductServiceTest { }

@SpringBootTest
class OrderStatisticsServiceTest {
    @MockBean MailSendClient mailSendClient;
    @MockBean SlackClient slackClient;
}

