# --- 부모로 되돌리면 ---

@ActiveProfiles("test")
@SpringBootTest
public abstract class IntegrationTestSupport {
    @MockBean protected MailSendClient mailSendClient;
    @MockBean protected SlackClient slackClient;
}

$ ./gradlew test 2>&1 | grep "cache statistics" | tail -1

    [size = 3, maxSize = 32, hitCount = 9, missCount = 3]

BUILD SUCCESSFUL in 31s

#   다시 3개, 31초다

#   ProductServiceTest 는 메일도 슬랙도 안 쓰는데 목이 떠 있다

#   그게 5.7절에서 말한 대가다

# --- 컨트롤러를 하나 더 만들면 ---

@WebMvcTest(controllers = ProductController.class)
class ProductControllerTest {
    @MockBean ProductService productService;
}

$ ./gradlew test 2>&1 | grep "cache statistics" | tail -1

    [size = 4, maxSize = 32, hitCount = 9, missCount = 4]

BUILD SUCCESSFUL in 34s

#   4개가 됐다

#   controllers 와 @MockBean 이 둘 다 다르다

# --- ControllerTestSupport 로 모으면 ---

@WebMvcTest(controllers = {OrderController.class, ProductController.class})
public abstract class ControllerTestSupport {
    @Autowired protected MockMvc mockMvc;
    @Autowired protected ObjectMapper objectMapper;
    @MockBean protected OrderService orderService;
    @MockBean protected ProductService productService;
}

$ ./gradlew test 2>&1 | grep "cache statistics" | tail -1

    [size = 3, maxSize = 32, hitCount = 10, missCount = 3]

BUILD SUCCESSFUL in 31s

#   다시 3개다

#   컨트롤러가 열이어도 3개다

# --- properties 를 인라인으로 쓰면 ---

@SpringBootTest(properties = "spring.jpa.show-sql=true")
class ShowSqlTest extends IntegrationTestSupport { }

$ ./gradlew test 2>&1 | grep "cache statistics" | tail -1

    [size = 4, maxSize = 32, hitCount = 10, missCount = 4]

